// PC Connection, 28 Nov 2026: the exported report had no page numbers, and
// sections could begin in the last few centimetres of a page. Both were
// measured in headless Chrome 158 with the report's own stylesheet:
// - the running footer is the page's bottom margin boxes: status, notice and
//   "Page X of Y" where "Generated by Audit360" was; all six boxes are defined
//   so Chrome's own date/URL never prints; the cover has no number. Margins
//   are 12 mm top and 18 mm bottom now that the footer left the page body.
// - a section starts a new page when less than half a page (125 mm) is left;
//   with more room it stays exactly where it was.
//
// execution-reporting.js is too DOM-dependent to load whole here (see
// tests/previous-findings-status.test.js), so the rules are read from the
// source and the spacer step is lifted out and run.
import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';

const SRC = fs.readFileSync(path.resolve('./execution-reporting.js'), 'utf8');

describe('running footer and page numbers', () => {
    // The @page rule as the export builds it, from the source.
    const pageRule = (label) => {
        const a = SRC.lastIndexOf('(function () {', SRC.indexOf('const cssStr'));
        const b = SRC.indexOf('})()', a) + 4;
        expect(a).toBeGreaterThan(0);
        // eslint-disable-next-line no-new-func
        return new Function('d', 'modifiedSinceIssue', 'window', 'return ' + SRC.slice(a, b))(
            { report: {} }, false, { _reportIssueLabel: () => label });
    };

    it('puts the status, the notice and "Page X of Y" in the bottom margin', () => {
        const css = pageRule('Final');
        expect(css).toContain('@bottom-left{content:"Confidential — Final";');
        expect(css).toContain('@bottom-center{content:"This document is confidential');
        expect(css).toContain('@bottom-right{content:"Page " counter(page) " of " counter(pages);');
    });

    it('no longer prints "Generated by Audit360" or a footer row in the page body', () => {
        expect(SRC).not.toContain('Generated by Audit360');
        expect(SRC).not.toContain('<tfoot>');
        expect(SRC).not.toMatch(/class="rpt-ftr/);
    });

    it('uses 12 mm top and 18 mm bottom margins, and equal side boxes so the rule is continuous', () => {
        const css = pageRule('Final');
        expect(css).toContain('@page{size:A4;margin:12mm 14mm 18mm 14mm;');
        expect(css.match(/width:(\d+)%/g)).toEqual(['width:25%', 'width:50%', 'width:25%']);
    });

    it('defines the top margin boxes empty, so the browser adds no date or URL', () => {
        const css = pageRule('Final');
        ['top-left', 'top-center', 'top-right'].forEach((b) => expect(css).toContain('@' + b + '{content:"";}'));
    });

    it('leaves the cover unnumbered, with an empty box rather than none', () => {
        expect(pageRule('Final')).toContain('@page :first{@bottom-right{content:"";}}');
    });

    it('escapes the status label for CSS', () => {
        expect(pageRule('Say "x" \\ <y>')).toContain('content:"Confidential — Say \\"x\\" \\\\ \\3C y>"');
    });
});

describe('a section starts a new page when less than half a page is left', () => {
    it('has an unbreakable 125 mm spacer whose margin takes its height back', () => {
        expect(SRC).toContain('.sec-keep{display:block;height:125mm;margin:34px 0 -125mm;break-inside:avoid;page-break-inside:avoid;break-after:avoid;page-break-after:avoid;}');
        expect(SRC).toContain('.sec-keep + .sh{margin-top:0;}');
        expect(SRC).toContain('@media screen{.sec-keep{display:none;}}');
    });

    it('puts the spacer before every section header except those that always open a page', () => {
        const a = SRC.indexOf('const SECTION_FORCED_PAGE');
        const b = SRC.indexOf('const reportHtmlFinal', a);
        expect(a).toBeGreaterThan(0);
        const html = ['exec-summary', 'objectives', 'audit-trails', 'summary', 'observations', 'conclusion', 'signature', 'distribution']
            .map((k) => '<div id="sec-' + k + '" class="sh" style="x">' + k + '</div><div class="sb"></div>').join('');
        // eslint-disable-next-line no-new-func
        const out = new Function('reportHtmlColored', SRC.slice(a, b) + '\nreturn reportHtmlKept;')(html);
        const spaced = [...out.matchAll(/<div class="sec-keep" aria-hidden="true"><\/div><div id="sec-([a-z-]+)"/g)].map((m) => m[1]);
        expect(spaced).toEqual(['exec-summary', 'audit-trails', 'observations', 'distribution']);
    });

    it('still forces those four onto a new page', () => {
        expect(SRC).toContain('#sec-objectives,#sec-summary,#sec-conclusion,#sec-signature{page-break-before:always;break-before:page;}');
    });
});
